"use client";
import type { CSSProperties } from "react";
import { ButtonSurface, buttonVariables, type AnimationButtonProps } from "./button-shared";
export interface TextUnderlineProps extends AnimationButtonProps {
  thickness?: number;
  offset?: number;
  underlineColor?: string;
}
const css = `
.z-anb-text-underline{min-height:29.2px;padding:0 0 var(--z-anb-offset,4px);border-radius:0;background:transparent;font-size:18px;font-weight:400;line-height:1.4}
.z-anb-underline{position:absolute;bottom:0;left:0;width:100%;height:var(--z-anb-thickness,1px);background:var(--z-anb-underline-color,currentColor);transform:scaleX(0);transform-origin:right center;transition:transform var(--z-anb-duration) var(--z-anb-easing);pointer-events:none}
.z-anb-text-underline[data-active=true] .z-anb-underline{transform:scaleX(1);transform-origin:left center}
`;
/** The underline draws from the left and erases toward the right. */
export function TextUnderline({
  children = "Shop Performance Collection",
  duration = 0.5,
  easing = "cubic-bezier(.16,1,.3,1)",
  thickness = 1,
  offset = 4,
  underlineColor = "currentColor",
  ...props
}: TextUnderlineProps) {
  return (
    <>
      <style>{css}</style>
      <ButtonSurface
        {...props}
        variant="text-underline"
        variables={
          {
            ...buttonVariables({ ...props, duration, easing }),
            "--z-anb-thickness": `${Math.max(0, thickness)}px`,
            "--z-anb-offset": `${Math.max(0, offset)}px`,
            "--z-anb-underline-color": underlineColor,
          } as CSSProperties
        }
      >
        <span className="z-anb-label">{children}</span>
        <span className="z-anb-underline" aria-hidden="true" />
      </ButtonSurface>
    </>
  );
}
